def last_position(
    texts: List[str]
) -> int:
    """Check returning an arithmetic over a length as an integer."""
    # pylint: disable=all
    return len(texts) - 1


def no_number_is_seven(
    numbers: List[int],
    count: int
) -> bool:
    """
    Check reading at the indices which are integers rather than lengths.
    """
    # pylint: disable=all
    for i in range(0, count):
        number = numbers[i]
        if number == 7:
            return False
        mirrored = numbers[(len(numbers) - 1) - i]
        if mirrored == 7:
            return False
        rotated = numbers[(i + 1) % len(numbers)]
        if rotated == 7:
            return False
    return True


def no_seven_from(
    numbers: List[int],
    start: int
) -> bool:
    """Check the ranges over the integers with a length as a bound."""
    # pylint: disable=all
    for i in range(start, len(numbers)):
        number = numbers[i]
        if number == 7:
            return False
    return (
        all(
            numbers[i] != 7
            for i in range(
                start,
                len(numbers)
            )
        ))


def fill_texts_from_both_ends(
    texts: List[str],
    count: int,
    text: str
) -> bool:
    """
    Check writing at the indices which are integers rather than lengths.
    """
    # pylint: disable=all
    for i in range(0, count):
        texts[i] = text
        texts[(len(texts) - 1) - i] = text
    return True


